func (s *Server) OnStart(_ event.Start) (err error) {
	//goland:noinspection GoResourceLeak captures the conn object which should NOT be closed
	playerData, err := server.ServeLogin(s.Conn, server.WithRawStatus(StatusResponse), server.WithCompatibleVersions(772))
	if err != nil {
		return
	}
	slog.Info("player logged in", "name", playerData.Requested.Name)
	err = server.ServeConfig(s.Conn)
	if err != nil {
		return
	}
	login := &v1_21_8.PlayToClientPacketLogin{EntityId: 73, IsHardcore: false, WorldNames: []string{"minecraft:overworld", "minecraft:the_end", "minecraft:the_nether"}, MaxPlayers: 100, ViewDistance: 10, SimulationDistance: 10, ReducedDebugInfo: false, EnableRespawnScreen: true, DoLimitedCrafting: false, WorldState: v1_21_8.PlayToClientSpawnInfo{Dimension: 0, Name: "minecraft:overworld", HashedSeed: -8365436745629239539, Gamemode: "survival", PreviousGamemode: 0xff, IsDebug: false, IsFlat: false, Death: nil, PortalCooldown: 0, SeaLevel: 63}, EnforcesSecureChat: false}
	err = s.Send(login)
	if err != nil {
		return
	}
	err = s.Send(&v1_21_8.PlayToClientPacketPosition{
		TeleportId: 0,
		X:          0,
		Y:          -60,
		Z:          0,
		Dx:         0,
		Dy:         0,
		Dz:         0,
		Yaw:        0,
		Pitch:      0,
		Flags:      v1_21_8.PlayToClientPositionUpdateRelatives{},
	})
	if err != nil {
		return
	}
	err = s.Send(&v1_21_8.PlayToClientPacketUpdateViewPosition{
		ChunkX: 0,
		ChunkZ: 0,
	})
	if err != nil {
		return
	}
	err = s.Send(&v1_21_8.PlayToClientPacketGameStateChange{
		Reason: "level_chunks_load_start",
	})
	for x := int32(-3); x < 3; x++ {
		for y := int32(-3); y < 3; y++ {
			if x == 0 && y == 0 {
				continue
			}
			voidChunk.X = x
			voidChunk.Z = y
			err = s.Send(voidChunk)
			if err != nil {
				return
			}
		}
	}

	err = s.Send(packet)
	if err != nil {
		return
	}
	s.Timer.Every(time.Second*15, s.SendKeepAlive)
	s.Timer.Every(time.Second*20, s.CycleBlockForTesting)
	s.Timer.Active = true
	return
}

func (s *Server) OnTick(_ event.Tick) (err error) {
	err = s.Timer.Tick()
	return
}

func (s *Server) CycleBlockForTesting() (err error) {
	_, stateData, err := data.FromBlockState(s.Version, s.Current)
	if err != nil {
		return
	}
	slog.Info("cycle block", "state", stateData, "cycle", s.Current)

	err = s.Send(&v1_21_8.PlayToClientPacketBlockChange{
		Location: v1_21_8.Position{
			X: 1,
			Z: 1,
			Y: -60,
		},
		Type: s.Current,
	})
	s.Current++
	if s.Current > s.MaxCycle {
		s.Current = s.MinCycle
	}
	return
}

func (s *Server) SendKeepAlive() (err error) {
	err = s.Send(&v1_21_8.PlayToClientPacketKeepAlive{KeepAliveId: rand.Int64()})
	if err != nil {
		return
	}
	return
}

func main() {
	slog.SetLogLoggerLevel(slog.LevelInfo)
	err := server.StartServerWithFactory(":25565", func(c *proto.Conn) (h any, err error) {
		s := &Server{Conn: c, MinCycle: 8297, MaxCycle: 8304, Current: 8297}
		s.Timer = &event.Timer{}
		h = s
		return
	})
	if err != nil {
		panic(err)
	}
}
